-- ============================================================
-- AdventureWorks OLTP 2014 (PostgreSQL port) -- schema only
--
-- Generated by benchmark_data/adventureworks/setup.py from the loaded
-- database, so it cannot drift from what it describes. This is what the
-- naive arm puts in its prompt, exactly as test_app_db/init/01_schema.sql
-- is for the car_rental set. Base tables only: views are omitted, most
-- being shorthand aliases (pe/hr/pr/pu/sa) that would only pad the prompt.
-- ============================================================

CREATE SCHEMA humanresources;
CREATE SCHEMA person;
CREATE SCHEMA production;
CREATE SCHEMA purchasing;
CREATE SCHEMA sales;

CREATE TABLE humanresources.department (
    departmentid                 INTEGER NOT NULL,
    name                         VARCHAR(50) NOT NULL,
    groupname                    VARCHAR(50) NOT NULL,
    modifieddate                 TIMESTAMP NOT NULL,
    PRIMARY KEY (departmentid)
);

CREATE TABLE humanresources.employee (
    businessentityid             INTEGER NOT NULL,
    nationalidnumber             VARCHAR(15) NOT NULL,
    loginid                      VARCHAR(256) NOT NULL,
    jobtitle                     VARCHAR(50) NOT NULL,
    birthdate                    DATE NOT NULL,
    maritalstatus                VARCHAR(1) NOT NULL,
    gender                       VARCHAR(1) NOT NULL,
    hiredate                     DATE NOT NULL,
    salariedflag                 BOOLEAN NOT NULL,
    vacationhours                SMALLINT NOT NULL,
    sickleavehours               SMALLINT NOT NULL,
    currentflag                  BOOLEAN NOT NULL,
    rowguid                      UUID NOT NULL,
    modifieddate                 TIMESTAMP NOT NULL,
    organizationnode             CHARACTER VARYING,
    PRIMARY KEY (businessentityid),
    FOREIGN KEY (businessentityid) REFERENCES person.person(businessentityid)
);

CREATE TABLE humanresources.employeedepartmenthistory (
    businessentityid             INTEGER NOT NULL,
    departmentid                 SMALLINT NOT NULL,
    shiftid                      SMALLINT NOT NULL,
    startdate                    DATE NOT NULL,
    enddate                      DATE,
    modifieddate                 TIMESTAMP NOT NULL,
    PRIMARY KEY (businessentityid, startdate, departmentid, shiftid),
    FOREIGN KEY (businessentityid) REFERENCES humanresources.employee(businessentityid),
    FOREIGN KEY (departmentid) REFERENCES humanresources.department(departmentid),
    FOREIGN KEY (shiftid) REFERENCES humanresources.shift(shiftid)
);

CREATE TABLE humanresources.employeepayhistory (
    businessentityid             INTEGER NOT NULL,
    ratechangedate               TIMESTAMP NOT NULL,
    rate                         NUMERIC NOT NULL,
    payfrequency                 SMALLINT NOT NULL,
    modifieddate                 TIMESTAMP NOT NULL,
    PRIMARY KEY (businessentityid, ratechangedate),
    FOREIGN KEY (businessentityid) REFERENCES humanresources.employee(businessentityid)
);

CREATE TABLE humanresources.jobcandidate (
    jobcandidateid               INTEGER NOT NULL,
    businessentityid             INTEGER,
    resume                       TEXT,
    modifieddate                 TIMESTAMP NOT NULL,
    PRIMARY KEY (jobcandidateid),
    FOREIGN KEY (businessentityid) REFERENCES humanresources.employee(businessentityid)
);

CREATE TABLE humanresources.shift (
    shiftid                      INTEGER NOT NULL,
    name                         VARCHAR(50) NOT NULL,
    starttime                    TIME WITHOUT TIME ZONE NOT NULL,
    endtime                      TIME WITHOUT TIME ZONE NOT NULL,
    modifieddate                 TIMESTAMP NOT NULL,
    PRIMARY KEY (shiftid)
);

CREATE TABLE person.address (
    addressid                    INTEGER NOT NULL,
    addressline1                 VARCHAR(60) NOT NULL,
    addressline2                 VARCHAR(60),
    city                         VARCHAR(30) NOT NULL,
    stateprovinceid              INTEGER NOT NULL,
    postalcode                   VARCHAR(15) NOT NULL,
    spatiallocation              VARCHAR(44),
    rowguid                      UUID NOT NULL,
    modifieddate                 TIMESTAMP NOT NULL,
    PRIMARY KEY (addressid),
    FOREIGN KEY (stateprovinceid) REFERENCES person.stateprovince(stateprovinceid)
);

CREATE TABLE person.addresstype (
    addresstypeid                INTEGER NOT NULL,
    name                         VARCHAR(50) NOT NULL,
    rowguid                      UUID NOT NULL,
    modifieddate                 TIMESTAMP NOT NULL,
    PRIMARY KEY (addresstypeid)
);

CREATE TABLE person.businessentity (
    businessentityid             INTEGER NOT NULL,
    rowguid                      UUID NOT NULL,
    modifieddate                 TIMESTAMP NOT NULL,
    PRIMARY KEY (businessentityid)
);

CREATE TABLE person.businessentityaddress (
    businessentityid             INTEGER NOT NULL,
    addressid                    INTEGER NOT NULL,
    addresstypeid                INTEGER NOT NULL,
    rowguid                      UUID NOT NULL,
    modifieddate                 TIMESTAMP NOT NULL,
    PRIMARY KEY (businessentityid, addressid, addresstypeid),
    FOREIGN KEY (addressid) REFERENCES person.address(addressid),
    FOREIGN KEY (addresstypeid) REFERENCES person.addresstype(addresstypeid),
    FOREIGN KEY (businessentityid) REFERENCES person.businessentity(businessentityid)
);

CREATE TABLE person.businessentitycontact (
    businessentityid             INTEGER NOT NULL,
    personid                     INTEGER NOT NULL,
    contacttypeid                INTEGER NOT NULL,
    rowguid                      UUID NOT NULL,
    modifieddate                 TIMESTAMP NOT NULL,
    PRIMARY KEY (businessentityid, personid, contacttypeid),
    FOREIGN KEY (businessentityid) REFERENCES person.businessentity(businessentityid),
    FOREIGN KEY (contacttypeid) REFERENCES person.contacttype(contacttypeid),
    FOREIGN KEY (personid) REFERENCES person.person(businessentityid)
);

CREATE TABLE person.contacttype (
    contacttypeid                INTEGER NOT NULL,
    name                         VARCHAR(50) NOT NULL,
    modifieddate                 TIMESTAMP NOT NULL,
    PRIMARY KEY (contacttypeid)
);

CREATE TABLE person.countryregion (
    countryregioncode            VARCHAR(3) NOT NULL,
    name                         VARCHAR(50) NOT NULL,
    modifieddate                 TIMESTAMP NOT NULL,
    PRIMARY KEY (countryregioncode)
);

CREATE TABLE person.emailaddress (
    businessentityid             INTEGER NOT NULL,
    emailaddressid               INTEGER NOT NULL,
    emailaddress                 VARCHAR(50),
    rowguid                      UUID NOT NULL,
    modifieddate                 TIMESTAMP NOT NULL,
    PRIMARY KEY (businessentityid, emailaddressid),
    FOREIGN KEY (businessentityid) REFERENCES person.person(businessentityid)
);

CREATE TABLE person.password (
    businessentityid             INTEGER NOT NULL,
    passwordhash                 VARCHAR(128) NOT NULL,
    passwordsalt                 VARCHAR(10) NOT NULL,
    rowguid                      UUID NOT NULL,
    modifieddate                 TIMESTAMP NOT NULL,
    PRIMARY KEY (businessentityid),
    FOREIGN KEY (businessentityid) REFERENCES person.person(businessentityid)
);

CREATE TABLE person.person (
    businessentityid             INTEGER NOT NULL,
    persontype                   VARCHAR(2) NOT NULL,
    namestyle                    BOOLEAN NOT NULL,
    title                        VARCHAR(8),
    firstname                    VARCHAR(50) NOT NULL,
    middlename                   VARCHAR(50),
    lastname                     VARCHAR(50) NOT NULL,
    suffix                       VARCHAR(10),
    emailpromotion               INTEGER NOT NULL,
    additionalcontactinfo        TEXT,
    demographics                 TEXT,
    rowguid                      UUID NOT NULL,
    modifieddate                 TIMESTAMP NOT NULL,
    PRIMARY KEY (businessentityid),
    FOREIGN KEY (businessentityid) REFERENCES person.businessentity(businessentityid)
);

CREATE TABLE person.personphone (
    businessentityid             INTEGER NOT NULL,
    phonenumber                  VARCHAR(25) NOT NULL,
    phonenumbertypeid            INTEGER NOT NULL,
    modifieddate                 TIMESTAMP NOT NULL,
    PRIMARY KEY (businessentityid, phonenumber, phonenumbertypeid),
    FOREIGN KEY (businessentityid) REFERENCES person.person(businessentityid),
    FOREIGN KEY (phonenumbertypeid) REFERENCES person.phonenumbertype(phonenumbertypeid)
);

CREATE TABLE person.phonenumbertype (
    phonenumbertypeid            INTEGER NOT NULL,
    name                         VARCHAR(50) NOT NULL,
    modifieddate                 TIMESTAMP NOT NULL,
    PRIMARY KEY (phonenumbertypeid)
);

CREATE TABLE person.stateprovince (
    stateprovinceid              INTEGER NOT NULL,
    stateprovincecode            VARCHAR(3) NOT NULL,
    countryregioncode            VARCHAR(3) NOT NULL,
    isonlystateprovinceflag      BOOLEAN NOT NULL,
    name                         VARCHAR(50) NOT NULL,
    territoryid                  INTEGER NOT NULL,
    rowguid                      UUID NOT NULL,
    modifieddate                 TIMESTAMP NOT NULL,
    PRIMARY KEY (stateprovinceid),
    FOREIGN KEY (countryregioncode) REFERENCES person.countryregion(countryregioncode),
    FOREIGN KEY (territoryid) REFERENCES sales.salesterritory(territoryid)
);

CREATE TABLE production.billofmaterials (
    billofmaterialsid            INTEGER NOT NULL,
    productassemblyid            INTEGER,
    componentid                  INTEGER NOT NULL,
    startdate                    TIMESTAMP NOT NULL,
    enddate                      TIMESTAMP,
    unitmeasurecode              VARCHAR(3) NOT NULL,
    bomlevel                     SMALLINT NOT NULL,
    perassemblyqty               NUMERIC(8,2) NOT NULL,
    modifieddate                 TIMESTAMP NOT NULL,
    PRIMARY KEY (billofmaterialsid),
    FOREIGN KEY (componentid) REFERENCES production.product(productid),
    FOREIGN KEY (productassemblyid) REFERENCES production.product(productid),
    FOREIGN KEY (unitmeasurecode) REFERENCES production.unitmeasure(unitmeasurecode)
);

CREATE TABLE production.culture (
    cultureid                    VARCHAR(6) NOT NULL,
    name                         VARCHAR(50) NOT NULL,
    modifieddate                 TIMESTAMP NOT NULL,
    PRIMARY KEY (cultureid)
);

CREATE TABLE production.document (
    title                        VARCHAR(50) NOT NULL,
    owner                        INTEGER NOT NULL,
    folderflag                   BOOLEAN NOT NULL,
    filename                     VARCHAR(400) NOT NULL,
    fileextension                VARCHAR(8),
    revision                     VARCHAR(5) NOT NULL,
    changenumber                 INTEGER NOT NULL,
    status                       SMALLINT NOT NULL,
    documentsummary              TEXT,
    document                     BYTEA,
    rowguid                      UUID NOT NULL,
    modifieddate                 TIMESTAMP NOT NULL,
    documentnode                 CHARACTER VARYING NOT NULL,
    PRIMARY KEY (documentnode),
    FOREIGN KEY (owner) REFERENCES humanresources.employee(businessentityid)
);

CREATE TABLE production.illustration (
    illustrationid               INTEGER NOT NULL,
    diagram                      TEXT,
    modifieddate                 TIMESTAMP NOT NULL,
    PRIMARY KEY (illustrationid)
);

CREATE TABLE production.location (
    locationid                   INTEGER NOT NULL,
    name                         VARCHAR(50) NOT NULL,
    costrate                     NUMERIC NOT NULL,
    availability                 NUMERIC(8,2) NOT NULL,
    modifieddate                 TIMESTAMP NOT NULL,
    PRIMARY KEY (locationid)
);

CREATE TABLE production.product (
    productid                    INTEGER NOT NULL,
    name                         VARCHAR(50) NOT NULL,
    productnumber                VARCHAR(25) NOT NULL,
    makeflag                     BOOLEAN NOT NULL,
    finishedgoodsflag            BOOLEAN NOT NULL,
    color                        VARCHAR(15),
    safetystocklevel             SMALLINT NOT NULL,
    reorderpoint                 SMALLINT NOT NULL,
    standardcost                 NUMERIC NOT NULL,
    listprice                    NUMERIC NOT NULL,
    size                         VARCHAR(5),
    sizeunitmeasurecode          VARCHAR(3),
    weightunitmeasurecode        VARCHAR(3),
    weight                       NUMERIC(8,2),
    daystomanufacture            INTEGER NOT NULL,
    productline                  VARCHAR(2),
    class                        VARCHAR(2),
    style                        VARCHAR(2),
    productsubcategoryid         INTEGER,
    productmodelid               INTEGER,
    sellstartdate                TIMESTAMP NOT NULL,
    sellenddate                  TIMESTAMP,
    discontinueddate             TIMESTAMP,
    rowguid                      UUID NOT NULL,
    modifieddate                 TIMESTAMP NOT NULL,
    PRIMARY KEY (productid),
    FOREIGN KEY (productmodelid) REFERENCES production.productmodel(productmodelid),
    FOREIGN KEY (productsubcategoryid) REFERENCES production.productsubcategory(productsubcategoryid),
    FOREIGN KEY (sizeunitmeasurecode) REFERENCES production.unitmeasure(unitmeasurecode),
    FOREIGN KEY (weightunitmeasurecode) REFERENCES production.unitmeasure(unitmeasurecode)
);

CREATE TABLE production.productcategory (
    productcategoryid            INTEGER NOT NULL,
    name                         VARCHAR(50) NOT NULL,
    rowguid                      UUID NOT NULL,
    modifieddate                 TIMESTAMP NOT NULL,
    PRIMARY KEY (productcategoryid)
);

CREATE TABLE production.productcosthistory (
    productid                    INTEGER NOT NULL,
    startdate                    TIMESTAMP NOT NULL,
    enddate                      TIMESTAMP,
    standardcost                 NUMERIC NOT NULL,
    modifieddate                 TIMESTAMP NOT NULL,
    PRIMARY KEY (productid, startdate),
    FOREIGN KEY (productid) REFERENCES production.product(productid)
);

CREATE TABLE production.productdescription (
    productdescriptionid         INTEGER NOT NULL,
    description                  VARCHAR(400) NOT NULL,
    rowguid                      UUID NOT NULL,
    modifieddate                 TIMESTAMP NOT NULL,
    PRIMARY KEY (productdescriptionid)
);

CREATE TABLE production.productdocument (
    productid                    INTEGER NOT NULL,
    modifieddate                 TIMESTAMP NOT NULL,
    documentnode                 CHARACTER VARYING NOT NULL,
    PRIMARY KEY (productid, documentnode),
    FOREIGN KEY (documentnode) REFERENCES production.document(documentnode),
    FOREIGN KEY (productid) REFERENCES production.product(productid)
);

CREATE TABLE production.productinventory (
    productid                    INTEGER NOT NULL,
    locationid                   SMALLINT NOT NULL,
    shelf                        VARCHAR(10) NOT NULL,
    bin                          SMALLINT NOT NULL,
    quantity                     SMALLINT NOT NULL,
    rowguid                      UUID NOT NULL,
    modifieddate                 TIMESTAMP NOT NULL,
    PRIMARY KEY (productid, locationid),
    FOREIGN KEY (locationid) REFERENCES production.location(locationid),
    FOREIGN KEY (productid) REFERENCES production.product(productid)
);

CREATE TABLE production.productlistpricehistory (
    productid                    INTEGER NOT NULL,
    startdate                    TIMESTAMP NOT NULL,
    enddate                      TIMESTAMP,
    listprice                    NUMERIC NOT NULL,
    modifieddate                 TIMESTAMP NOT NULL,
    PRIMARY KEY (productid, startdate),
    FOREIGN KEY (productid) REFERENCES production.product(productid)
);

CREATE TABLE production.productmodel (
    productmodelid               INTEGER NOT NULL,
    name                         VARCHAR(50) NOT NULL,
    catalogdescription           TEXT,
    instructions                 TEXT,
    rowguid                      UUID NOT NULL,
    modifieddate                 TIMESTAMP NOT NULL,
    PRIMARY KEY (productmodelid)
);

CREATE TABLE production.productmodelillustration (
    productmodelid               INTEGER NOT NULL,
    illustrationid               INTEGER NOT NULL,
    modifieddate                 TIMESTAMP NOT NULL,
    PRIMARY KEY (productmodelid, illustrationid),
    FOREIGN KEY (illustrationid) REFERENCES production.illustration(illustrationid),
    FOREIGN KEY (productmodelid) REFERENCES production.productmodel(productmodelid)
);

CREATE TABLE production.productmodelproductdescriptionculture (
    productmodelid               INTEGER NOT NULL,
    productdescriptionid         INTEGER NOT NULL,
    cultureid                    VARCHAR(6) NOT NULL,
    modifieddate                 TIMESTAMP NOT NULL,
    PRIMARY KEY (productmodelid, productdescriptionid, cultureid),
    FOREIGN KEY (cultureid) REFERENCES production.culture(cultureid),
    FOREIGN KEY (productdescriptionid) REFERENCES production.productdescription(productdescriptionid),
    FOREIGN KEY (productmodelid) REFERENCES production.productmodel(productmodelid)
);

CREATE TABLE production.productphoto (
    productphotoid               INTEGER NOT NULL,
    thumbnailphoto               BYTEA,
    thumbnailphotofilename       VARCHAR(50),
    largephoto                   BYTEA,
    largephotofilename           VARCHAR(50),
    modifieddate                 TIMESTAMP NOT NULL,
    PRIMARY KEY (productphotoid)
);

CREATE TABLE production.productproductphoto (
    productid                    INTEGER NOT NULL,
    productphotoid               INTEGER NOT NULL,
    primary                      BOOLEAN NOT NULL,
    modifieddate                 TIMESTAMP NOT NULL,
    PRIMARY KEY (productid, productphotoid),
    FOREIGN KEY (productid) REFERENCES production.product(productid),
    FOREIGN KEY (productphotoid) REFERENCES production.productphoto(productphotoid)
);

CREATE TABLE production.productreview (
    productreviewid              INTEGER NOT NULL,
    productid                    INTEGER NOT NULL,
    reviewername                 VARCHAR(50) NOT NULL,
    reviewdate                   TIMESTAMP NOT NULL,
    emailaddress                 VARCHAR(50) NOT NULL,
    rating                       INTEGER NOT NULL,
    comments                     VARCHAR(3850),
    modifieddate                 TIMESTAMP NOT NULL,
    PRIMARY KEY (productreviewid),
    FOREIGN KEY (productid) REFERENCES production.product(productid)
);

CREATE TABLE production.productsubcategory (
    productsubcategoryid         INTEGER NOT NULL,
    productcategoryid            INTEGER NOT NULL,
    name                         VARCHAR(50) NOT NULL,
    rowguid                      UUID NOT NULL,
    modifieddate                 TIMESTAMP NOT NULL,
    PRIMARY KEY (productsubcategoryid),
    FOREIGN KEY (productcategoryid) REFERENCES production.productcategory(productcategoryid)
);

CREATE TABLE production.scrapreason (
    scrapreasonid                INTEGER NOT NULL,
    name                         VARCHAR(50) NOT NULL,
    modifieddate                 TIMESTAMP NOT NULL,
    PRIMARY KEY (scrapreasonid)
);

CREATE TABLE production.transactionhistory (
    transactionid                INTEGER NOT NULL,
    productid                    INTEGER NOT NULL,
    referenceorderid             INTEGER NOT NULL,
    referenceorderlineid         INTEGER NOT NULL,
    transactiondate              TIMESTAMP NOT NULL,
    transactiontype              VARCHAR(1) NOT NULL,
    quantity                     INTEGER NOT NULL,
    actualcost                   NUMERIC NOT NULL,
    modifieddate                 TIMESTAMP NOT NULL,
    PRIMARY KEY (transactionid),
    FOREIGN KEY (productid) REFERENCES production.product(productid)
);

CREATE TABLE production.transactionhistoryarchive (
    transactionid                INTEGER NOT NULL,
    productid                    INTEGER NOT NULL,
    referenceorderid             INTEGER NOT NULL,
    referenceorderlineid         INTEGER NOT NULL,
    transactiondate              TIMESTAMP NOT NULL,
    transactiontype              VARCHAR(1) NOT NULL,
    quantity                     INTEGER NOT NULL,
    actualcost                   NUMERIC NOT NULL,
    modifieddate                 TIMESTAMP NOT NULL,
    PRIMARY KEY (transactionid)
);

CREATE TABLE production.unitmeasure (
    unitmeasurecode              VARCHAR(3) NOT NULL,
    name                         VARCHAR(50) NOT NULL,
    modifieddate                 TIMESTAMP NOT NULL,
    PRIMARY KEY (unitmeasurecode)
);

CREATE TABLE production.workorder (
    workorderid                  INTEGER NOT NULL,
    productid                    INTEGER NOT NULL,
    orderqty                     INTEGER NOT NULL,
    scrappedqty                  SMALLINT NOT NULL,
    startdate                    TIMESTAMP NOT NULL,
    enddate                      TIMESTAMP,
    duedate                      TIMESTAMP NOT NULL,
    scrapreasonid                SMALLINT,
    modifieddate                 TIMESTAMP NOT NULL,
    PRIMARY KEY (workorderid),
    FOREIGN KEY (productid) REFERENCES production.product(productid),
    FOREIGN KEY (scrapreasonid) REFERENCES production.scrapreason(scrapreasonid)
);

CREATE TABLE production.workorderrouting (
    workorderid                  INTEGER NOT NULL,
    productid                    INTEGER NOT NULL,
    operationsequence            SMALLINT NOT NULL,
    locationid                   SMALLINT NOT NULL,
    scheduledstartdate           TIMESTAMP NOT NULL,
    scheduledenddate             TIMESTAMP NOT NULL,
    actualstartdate              TIMESTAMP,
    actualenddate                TIMESTAMP,
    actualresourcehrs            NUMERIC(9,4),
    plannedcost                  NUMERIC NOT NULL,
    actualcost                   NUMERIC,
    modifieddate                 TIMESTAMP NOT NULL,
    PRIMARY KEY (workorderid, productid, operationsequence),
    FOREIGN KEY (locationid) REFERENCES production.location(locationid),
    FOREIGN KEY (workorderid) REFERENCES production.workorder(workorderid)
);

CREATE TABLE purchasing.productvendor (
    productid                    INTEGER NOT NULL,
    businessentityid             INTEGER NOT NULL,
    averageleadtime              INTEGER NOT NULL,
    standardprice                NUMERIC NOT NULL,
    lastreceiptcost              NUMERIC,
    lastreceiptdate              TIMESTAMP,
    minorderqty                  INTEGER NOT NULL,
    maxorderqty                  INTEGER NOT NULL,
    onorderqty                   INTEGER,
    unitmeasurecode              VARCHAR(3) NOT NULL,
    modifieddate                 TIMESTAMP NOT NULL,
    PRIMARY KEY (productid, businessentityid),
    FOREIGN KEY (businessentityid) REFERENCES purchasing.vendor(businessentityid),
    FOREIGN KEY (productid) REFERENCES production.product(productid),
    FOREIGN KEY (unitmeasurecode) REFERENCES production.unitmeasure(unitmeasurecode)
);

CREATE TABLE purchasing.purchaseorderdetail (
    purchaseorderid              INTEGER NOT NULL,
    purchaseorderdetailid        INTEGER NOT NULL,
    duedate                      TIMESTAMP NOT NULL,
    orderqty                     SMALLINT NOT NULL,
    productid                    INTEGER NOT NULL,
    unitprice                    NUMERIC NOT NULL,
    receivedqty                  NUMERIC(8,2) NOT NULL,
    rejectedqty                  NUMERIC(8,2) NOT NULL,
    modifieddate                 TIMESTAMP NOT NULL,
    PRIMARY KEY (purchaseorderid, purchaseorderdetailid),
    FOREIGN KEY (productid) REFERENCES production.product(productid),
    FOREIGN KEY (purchaseorderid) REFERENCES purchasing.purchaseorderheader(purchaseorderid)
);

CREATE TABLE purchasing.purchaseorderheader (
    purchaseorderid              INTEGER NOT NULL,
    revisionnumber               SMALLINT NOT NULL,
    status                       SMALLINT NOT NULL,
    employeeid                   INTEGER NOT NULL,
    vendorid                     INTEGER NOT NULL,
    shipmethodid                 INTEGER NOT NULL,
    orderdate                    TIMESTAMP NOT NULL,
    shipdate                     TIMESTAMP,
    subtotal                     NUMERIC NOT NULL,
    taxamt                       NUMERIC NOT NULL,
    freight                      NUMERIC NOT NULL,
    modifieddate                 TIMESTAMP NOT NULL,
    PRIMARY KEY (purchaseorderid),
    FOREIGN KEY (employeeid) REFERENCES humanresources.employee(businessentityid),
    FOREIGN KEY (shipmethodid) REFERENCES purchasing.shipmethod(shipmethodid),
    FOREIGN KEY (vendorid) REFERENCES purchasing.vendor(businessentityid)
);

CREATE TABLE purchasing.shipmethod (
    shipmethodid                 INTEGER NOT NULL,
    name                         VARCHAR(50) NOT NULL,
    shipbase                     NUMERIC NOT NULL,
    shiprate                     NUMERIC NOT NULL,
    rowguid                      UUID NOT NULL,
    modifieddate                 TIMESTAMP NOT NULL,
    PRIMARY KEY (shipmethodid)
);

CREATE TABLE purchasing.vendor (
    businessentityid             INTEGER NOT NULL,
    accountnumber                VARCHAR(15) NOT NULL,
    name                         VARCHAR(50) NOT NULL,
    creditrating                 SMALLINT NOT NULL,
    preferredvendorstatus        BOOLEAN NOT NULL,
    activeflag                   BOOLEAN NOT NULL,
    purchasingwebserviceurl      VARCHAR(1024),
    modifieddate                 TIMESTAMP NOT NULL,
    PRIMARY KEY (businessentityid),
    FOREIGN KEY (businessentityid) REFERENCES person.businessentity(businessentityid)
);

CREATE TABLE sales.countryregioncurrency (
    countryregioncode            VARCHAR(3) NOT NULL,
    currencycode                 VARCHAR(3) NOT NULL,
    modifieddate                 TIMESTAMP NOT NULL,
    PRIMARY KEY (countryregioncode, currencycode),
    FOREIGN KEY (countryregioncode) REFERENCES person.countryregion(countryregioncode),
    FOREIGN KEY (currencycode) REFERENCES sales.currency(currencycode)
);

CREATE TABLE sales.creditcard (
    creditcardid                 INTEGER NOT NULL,
    cardtype                     VARCHAR(50) NOT NULL,
    cardnumber                   VARCHAR(25) NOT NULL,
    expmonth                     SMALLINT NOT NULL,
    expyear                      SMALLINT NOT NULL,
    modifieddate                 TIMESTAMP NOT NULL,
    PRIMARY KEY (creditcardid)
);

CREATE TABLE sales.currency (
    currencycode                 VARCHAR(3) NOT NULL,
    name                         VARCHAR(50) NOT NULL,
    modifieddate                 TIMESTAMP NOT NULL,
    PRIMARY KEY (currencycode)
);

CREATE TABLE sales.currencyrate (
    currencyrateid               INTEGER NOT NULL,
    currencyratedate             TIMESTAMP NOT NULL,
    fromcurrencycode             VARCHAR(3) NOT NULL,
    tocurrencycode               VARCHAR(3) NOT NULL,
    averagerate                  NUMERIC NOT NULL,
    endofdayrate                 NUMERIC NOT NULL,
    modifieddate                 TIMESTAMP NOT NULL,
    PRIMARY KEY (currencyrateid),
    FOREIGN KEY (fromcurrencycode) REFERENCES sales.currency(currencycode),
    FOREIGN KEY (tocurrencycode) REFERENCES sales.currency(currencycode)
);

CREATE TABLE sales.customer (
    customerid                   INTEGER NOT NULL,
    personid                     INTEGER,
    storeid                      INTEGER,
    territoryid                  INTEGER,
    rowguid                      UUID NOT NULL,
    modifieddate                 TIMESTAMP NOT NULL,
    PRIMARY KEY (customerid),
    FOREIGN KEY (personid) REFERENCES person.person(businessentityid),
    FOREIGN KEY (storeid) REFERENCES sales.store(businessentityid),
    FOREIGN KEY (territoryid) REFERENCES sales.salesterritory(territoryid)
);

CREATE TABLE sales.personcreditcard (
    businessentityid             INTEGER NOT NULL,
    creditcardid                 INTEGER NOT NULL,
    modifieddate                 TIMESTAMP NOT NULL,
    PRIMARY KEY (businessentityid, creditcardid),
    FOREIGN KEY (businessentityid) REFERENCES person.person(businessentityid),
    FOREIGN KEY (creditcardid) REFERENCES sales.creditcard(creditcardid)
);

CREATE TABLE sales.salesorderdetail (
    salesorderid                 INTEGER NOT NULL,
    salesorderdetailid           INTEGER NOT NULL,
    carriertrackingnumber        VARCHAR(25),
    orderqty                     SMALLINT NOT NULL,
    productid                    INTEGER NOT NULL,
    specialofferid               INTEGER NOT NULL,
    unitprice                    NUMERIC NOT NULL,
    unitpricediscount            NUMERIC NOT NULL,
    rowguid                      UUID NOT NULL,
    modifieddate                 TIMESTAMP NOT NULL,
    PRIMARY KEY (salesorderid, salesorderdetailid),
    FOREIGN KEY (productid) REFERENCES sales.specialofferproduct(productid),
    FOREIGN KEY (salesorderid) REFERENCES sales.salesorderheader(salesorderid),
    FOREIGN KEY (specialofferid) REFERENCES sales.specialofferproduct(specialofferid)
);

CREATE TABLE sales.salesorderheader (
    salesorderid                 INTEGER NOT NULL,
    revisionnumber               SMALLINT NOT NULL,
    orderdate                    TIMESTAMP NOT NULL,
    duedate                      TIMESTAMP NOT NULL,
    shipdate                     TIMESTAMP,
    status                       SMALLINT NOT NULL,
    onlineorderflag              BOOLEAN NOT NULL,
    purchaseordernumber          VARCHAR(25),
    accountnumber                VARCHAR(15),
    customerid                   INTEGER NOT NULL,
    salespersonid                INTEGER,
    territoryid                  INTEGER,
    billtoaddressid              INTEGER NOT NULL,
    shiptoaddressid              INTEGER NOT NULL,
    shipmethodid                 INTEGER NOT NULL,
    creditcardid                 INTEGER,
    creditcardapprovalcode       VARCHAR(15),
    currencyrateid               INTEGER,
    subtotal                     NUMERIC NOT NULL,
    taxamt                       NUMERIC NOT NULL,
    freight                      NUMERIC NOT NULL,
    totaldue                     NUMERIC,
    comment                      VARCHAR(128),
    rowguid                      UUID NOT NULL,
    modifieddate                 TIMESTAMP NOT NULL,
    PRIMARY KEY (salesorderid),
    FOREIGN KEY (billtoaddressid) REFERENCES person.address(addressid),
    FOREIGN KEY (creditcardid) REFERENCES sales.creditcard(creditcardid),
    FOREIGN KEY (currencyrateid) REFERENCES sales.currencyrate(currencyrateid),
    FOREIGN KEY (customerid) REFERENCES sales.customer(customerid),
    FOREIGN KEY (salespersonid) REFERENCES sales.salesperson(businessentityid),
    FOREIGN KEY (shipmethodid) REFERENCES purchasing.shipmethod(shipmethodid),
    FOREIGN KEY (shiptoaddressid) REFERENCES person.address(addressid),
    FOREIGN KEY (territoryid) REFERENCES sales.salesterritory(territoryid)
);

CREATE TABLE sales.salesorderheadersalesreason (
    salesorderid                 INTEGER NOT NULL,
    salesreasonid                INTEGER NOT NULL,
    modifieddate                 TIMESTAMP NOT NULL,
    PRIMARY KEY (salesorderid, salesreasonid),
    FOREIGN KEY (salesorderid) REFERENCES sales.salesorderheader(salesorderid),
    FOREIGN KEY (salesreasonid) REFERENCES sales.salesreason(salesreasonid)
);

CREATE TABLE sales.salesperson (
    businessentityid             INTEGER NOT NULL,
    territoryid                  INTEGER,
    salesquota                   NUMERIC,
    bonus                        NUMERIC NOT NULL,
    commissionpct                NUMERIC NOT NULL,
    salesytd                     NUMERIC NOT NULL,
    saleslastyear                NUMERIC NOT NULL,
    rowguid                      UUID NOT NULL,
    modifieddate                 TIMESTAMP NOT NULL,
    PRIMARY KEY (businessentityid),
    FOREIGN KEY (businessentityid) REFERENCES humanresources.employee(businessentityid),
    FOREIGN KEY (territoryid) REFERENCES sales.salesterritory(territoryid)
);

CREATE TABLE sales.salespersonquotahistory (
    businessentityid             INTEGER NOT NULL,
    quotadate                    TIMESTAMP NOT NULL,
    salesquota                   NUMERIC NOT NULL,
    rowguid                      UUID NOT NULL,
    modifieddate                 TIMESTAMP NOT NULL,
    PRIMARY KEY (businessentityid, quotadate),
    FOREIGN KEY (businessentityid) REFERENCES sales.salesperson(businessentityid)
);

CREATE TABLE sales.salesreason (
    salesreasonid                INTEGER NOT NULL,
    name                         VARCHAR(50) NOT NULL,
    reasontype                   VARCHAR(50) NOT NULL,
    modifieddate                 TIMESTAMP NOT NULL,
    PRIMARY KEY (salesreasonid)
);

CREATE TABLE sales.salestaxrate (
    salestaxrateid               INTEGER NOT NULL,
    stateprovinceid              INTEGER NOT NULL,
    taxtype                      SMALLINT NOT NULL,
    taxrate                      NUMERIC NOT NULL,
    name                         VARCHAR(50) NOT NULL,
    rowguid                      UUID NOT NULL,
    modifieddate                 TIMESTAMP NOT NULL,
    PRIMARY KEY (salestaxrateid),
    FOREIGN KEY (stateprovinceid) REFERENCES person.stateprovince(stateprovinceid)
);

CREATE TABLE sales.salesterritory (
    territoryid                  INTEGER NOT NULL,
    name                         VARCHAR(50) NOT NULL,
    countryregioncode            VARCHAR(3) NOT NULL,
    group                        VARCHAR(50) NOT NULL,
    salesytd                     NUMERIC NOT NULL,
    saleslastyear                NUMERIC NOT NULL,
    costytd                      NUMERIC NOT NULL,
    costlastyear                 NUMERIC NOT NULL,
    rowguid                      UUID NOT NULL,
    modifieddate                 TIMESTAMP NOT NULL,
    PRIMARY KEY (territoryid),
    FOREIGN KEY (countryregioncode) REFERENCES person.countryregion(countryregioncode)
);

CREATE TABLE sales.salesterritoryhistory (
    businessentityid             INTEGER NOT NULL,
    territoryid                  INTEGER NOT NULL,
    startdate                    TIMESTAMP NOT NULL,
    enddate                      TIMESTAMP,
    rowguid                      UUID NOT NULL,
    modifieddate                 TIMESTAMP NOT NULL,
    PRIMARY KEY (businessentityid, startdate, territoryid),
    FOREIGN KEY (businessentityid) REFERENCES sales.salesperson(businessentityid),
    FOREIGN KEY (territoryid) REFERENCES sales.salesterritory(territoryid)
);

CREATE TABLE sales.shoppingcartitem (
    shoppingcartitemid           INTEGER NOT NULL,
    shoppingcartid               VARCHAR(50) NOT NULL,
    quantity                     INTEGER NOT NULL,
    productid                    INTEGER NOT NULL,
    datecreated                  TIMESTAMP NOT NULL,
    modifieddate                 TIMESTAMP NOT NULL,
    PRIMARY KEY (shoppingcartitemid),
    FOREIGN KEY (productid) REFERENCES production.product(productid)
);

CREATE TABLE sales.specialoffer (
    specialofferid               INTEGER NOT NULL,
    description                  VARCHAR(255) NOT NULL,
    discountpct                  NUMERIC NOT NULL,
    type                         VARCHAR(50) NOT NULL,
    category                     VARCHAR(50) NOT NULL,
    startdate                    TIMESTAMP NOT NULL,
    enddate                      TIMESTAMP NOT NULL,
    minqty                       INTEGER NOT NULL,
    maxqty                       INTEGER,
    rowguid                      UUID NOT NULL,
    modifieddate                 TIMESTAMP NOT NULL,
    PRIMARY KEY (specialofferid)
);

CREATE TABLE sales.specialofferproduct (
    specialofferid               INTEGER NOT NULL,
    productid                    INTEGER NOT NULL,
    rowguid                      UUID NOT NULL,
    modifieddate                 TIMESTAMP NOT NULL,
    PRIMARY KEY (specialofferid, productid),
    FOREIGN KEY (productid) REFERENCES production.product(productid),
    FOREIGN KEY (specialofferid) REFERENCES sales.specialoffer(specialofferid)
);

CREATE TABLE sales.store (
    businessentityid             INTEGER NOT NULL,
    name                         VARCHAR(50) NOT NULL,
    salespersonid                INTEGER,
    demographics                 TEXT,
    rowguid                      UUID NOT NULL,
    modifieddate                 TIMESTAMP NOT NULL,
    PRIMARY KEY (businessentityid),
    FOREIGN KEY (businessentityid) REFERENCES person.businessentity(businessentityid),
    FOREIGN KEY (salespersonid) REFERENCES sales.salesperson(businessentityid)
);
